sys_ws_operation.operation_script:
(function process(request, response) {
    try {
        var folderType = ("" + request.queryParams.type + "" || '')
            .toLowerCase()
            .replace(/\s/g, '');

        var folderId = request.queryParams.folderId;

        gs.info('Folder type: ' + folderType);
        gs.info('Folder ID: ' + folderId);

        var userId = gs.getUserID();
        var gr = new GlideRecord('x_1955226_connecto_report');
        gr.addActiveQuery();

        // 🔥 1. If folderId is provided → ignore type and filter by ID
        if (folderId) {
            gr.addQuery('folderid', folderId);

        // 🔹 2. Otherwise apply type filters
        } else if (folderType === 'createdbymereports') {
            gr.addQuery('sys_created_by', userId);

        } else if (folderType === 'sharedwithmereports') {
            gr.addQuery('shared_with', 'CONTAINS', userId);

        } else if (folderType === 'publicreports') {
            gr.addQuery('is_public', true);

        } else {
            gs.info('No filter applied, returning all reports');
        }

        gs.info('Encoded query: ' + gr.getEncodedQuery());

        gr.query();

        var reports = [];
        while (gr.next()) {

            reports.push({
                sys_id: gr.getValue('sys_id'),
                name: gr.getValue('name'),
                folderid: gr.getValue('folderid'),
                shared_with: gr.getValue('shared_with'),
                is_public: gr.getValue('is_public') === 'true',
				createdDate: gr.getValue('sys_created_on'),
				description: gr.getValue('description')
            });
        }

        response.setStatus(200);
        response.setBody({ success: true, reports });

    } catch (err) {
        response.setStatus(500);
        response.setBody({ success: false, message: err.message });
    }
})(request, response);
